                ],
                [
                    'color'             => $this->randomHexColor(),
                    'national_registry' => (string) $item['cnpj'],
                    'name'              => (string) mb_convert_case(
                        ($item['nome_fantasia'] ?? $item['razao_social']),
                        MB_CASE_TITLE,
                        'UTF-8'
                    ),
                    'company_name' => (string) mb_convert_case(
